pragma solidity >=0.8.0;

contract TimestampPairProbe {
    uint256 public firstSeen;
    uint256 public secondSeen;
    uint256 public count;

    event Seen(uint256 idx, uint256 ts, address by);

    function snapshot(uint256 idx) public {
        uint256 t = block.timestamp;
        if (idx == 0) {
            firstSeen = t;
        } else {
            secondSeen = t;
        }
        count += 1;
        emit Seen(idx, t, msg.sender);
    }

    function getNow() public view returns (uint256) {
        return block.timestamp;
    }

    function markSecond() public {
        secondSeen = block.timestamp;
        count += 2;
    }
}
